begin;
create schema if not exists print;
create table print.companies(id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 160));
create table print.memberships(company_id uuid references print.companies on delete cascade, user_id uuid references auth.users on delete cascade, role text not null check(role in ('owner','staff')), primary key(company_id,user_id));
create table print.products(company_id uuid references print.companies, id uuid default gen_random_uuid(), name text not null, price_cents integer check(price_cents>=0), active boolean not null default false, primary key(company_id,id));
create table print.orders(company_id uuid references print.companies, id uuid default gen_random_uuid(), product_id uuid not null, quantity integer not null check(quantity between 1 and 10000), color text not null, size text not null, side text not null check(side in ('front','back')), print_width_cm numeric not null check(print_width_cm between 3 and 40), scale_percent numeric not null check(scale_percent between 10 and 65), vertical_percent numeric not null check(vertical_percent between 28 and 64), artwork_path text not null, status text not null default 'draft' check(status in ('draft','requested','quoted','approved','in_production','ready','completed','cancelled')), quote_cents integer check(quote_cents>=0), created_at timestamptz not null default now(), primary key(company_id,id), foreign key(company_id,product_id) references print.products(company_id,id), check(split_part(artwork_path,'/',1)=company_id::text));
alter table print.companies enable row level security;
alter table print.memberships enable row level security;
alter table print.products enable row level security;
alter table print.orders enable row level security;
revoke all on schema print from public, anon, authenticated;
grant usage on schema print to authenticated, service_role;
revoke all on all tables in schema print from public, anon, authenticated;
grant select on print.companies,print.memberships to authenticated;
grant select,insert,update on print.products,print.orders to authenticated;
grant all on all tables in schema print to service_role;
create policy membership_self on print.memberships for select to authenticated using(user_id=(select auth.uid()));
create policy company_read on print.companies for select to authenticated using(exists(select 1 from print.memberships m where m.company_id=companies.id and m.user_id=(select auth.uid())));
create policy product_read on print.products for select to authenticated using(exists(select 1 from print.memberships m where m.company_id=products.company_id and m.user_id=(select auth.uid())));
create policy product_insert on print.products for insert to authenticated with check(exists(select 1 from print.memberships m where m.company_id=products.company_id and m.user_id=(select auth.uid()) and m.role='owner'));
create policy product_update on print.products for update to authenticated using(exists(select 1 from print.memberships m where m.company_id=products.company_id and m.user_id=(select auth.uid()) and m.role='owner')) with check(exists(select 1 from print.memberships m where m.company_id=products.company_id and m.user_id=(select auth.uid()) and m.role='owner'));
create policy order_read on print.orders for select to authenticated using(exists(select 1 from print.memberships m where m.company_id=orders.company_id and m.user_id=(select auth.uid())));
create policy order_insert on print.orders for insert to authenticated with check(status='draft' and quote_cents is null and exists(select 1 from print.memberships m where m.company_id=orders.company_id and m.user_id=(select auth.uid())));
-- Updates intentionally disabled until server-side lifecycle RPC is implemented.
revoke update on print.orders from authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('print-artworks','print-artworks',false,10485760,array['image/png','image/jpeg','image/webp']);
create policy print_art_read on storage.objects for select to authenticated using(bucket_id='print-artworks' and exists(select 1 from print.memberships m where m.company_id::text=split_part(name,'/',1) and m.user_id=(select auth.uid())));
create policy print_art_insert on storage.objects for insert to authenticated with check(bucket_id='print-artworks' and exists(select 1 from print.memberships m where m.company_id::text=split_part(name,'/',1) and m.user_id=(select auth.uid())));
commit;
